CREATE TABLE "admin_command_abort" (
  id INTEGER NOT NULL PRIMARY KEY CHECK (id = 0)
,
  CHECK ("id" IS NULL OR "id" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "audit_event" (
  id TEXT NOT NULL PRIMARY KEY,
  actor_user_id TEXT,
  action TEXT NOT NULL,
  aggregate_type TEXT NOT NULL,
  aggregate_id TEXT NOT NULL,
  details_json TEXT NOT NULL,
  idempotency_key TEXT,
  occurred_at INTEGER NOT NULL,
  market_id TEXT,
  location_id TEXT,
  reason TEXT,
  before_json TEXT,
  after_json TEXT,
  correlation_id TEXT
,
  CHECK ("occurred_at" IS NULL OR "occurred_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "capacity_allocations" (
  id TEXT NOT NULL PRIMARY KEY,
  cycle_id TEXT NOT NULL REFERENCES delivery_cycle(id) ON DELETE RESTRICT,
  zone_id TEXT NOT NULL REFERENCES delivery_zone(id) ON DELETE RESTRICT,
  location_id TEXT NOT NULL REFERENCES fulfillment_location(id) ON DELETE RESTRICT,
  checkout_attempt_id TEXT,
  order_id TEXT,
  units INTEGER NOT NULL DEFAULT 1 CHECK (units > 0),
  status TEXT NOT NULL CHECK (status IN ('HELD', 'COMMITTED', 'RELEASED', 'EXPIRED')),
  expires_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (checkout_attempt_id),
  UNIQUE (order_id)
,
  CHECK ("units" IS NULL OR "units" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("expires_at" IS NULL OR "expires_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "cart" (
  id TEXT NOT NULL PRIMARY KEY,
  customer_id TEXT NOT NULL REFERENCES customer(id),
  location_id TEXT NOT NULL REFERENCES fulfillment_location(id),
  status TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
,
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "cart_item" (
  cart_id TEXT NOT NULL REFERENCES cart(id) ON DELETE CASCADE,
  sku_id TEXT NOT NULL REFERENCES sku(id),
  quantity INTEGER NOT NULL CHECK(quantity > 0),
  PRIMARY KEY(cart_id, sku_id)
,
  CHECK ("quantity" IS NULL OR "quantity" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "category" (
  id TEXT PRIMARY KEY NOT NULL,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('active', 'inactive')),
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  icon_asset_key TEXT
  CHECK (
    icon_asset_key IS NULL OR (
      icon_asset_key NOT LIKE '%/%' AND
      icon_asset_key NOT LIKE '%\%' AND
      icon_asset_key NOT LIKE '%..%' AND
      icon_asset_key LIKE '%.svg'
    )
  ),
  parent_id TEXT NULL REFERENCES category(id) ON DELETE RESTRICT,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0)
,
