CREATE TABLE "committed_demand" (
  id TEXT NOT NULL PRIMARY KEY,
  order_id TEXT NOT NULL REFERENCES grocery_order(id),
  delivery_cycle_id TEXT NOT NULL REFERENCES delivery_cycle(id) ON DELETE RESTRICT,
  location_id TEXT NOT NULL REFERENCES fulfillment_location(id) ON DELETE RESTRICT,
  inventory_pool_id TEXT NOT NULL REFERENCES inventory_pool(id) ON DELETE RESTRICT,
  quantity INTEGER NOT NULL,
  status TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  demand_basis TEXT NOT NULL DEFAULT 'LEGACY_POOL_BASE'
  CHECK (demand_basis IN ('LEGACY_POOL_BASE', 'EXACT_PAID_LINE')),
  order_item_id TEXT REFERENCES order_item(id),
  sku_id TEXT REFERENCES sku(id),
  quantity_sellable INTEGER
  CHECK (quantity_sellable IS NULL OR quantity_sellable > 0),
  quantity_base_total INTEGER
  CHECK (quantity_base_total IS NULL OR quantity_base_total > 0),
  base_unit_code TEXT
  CHECK (base_unit_code IS NULL OR base_unit_code IN ('GRAM', 'MILLILITER', 'PIECE')),
  shipping_weight_grams INTEGER
  CHECK (shipping_weight_grams IS NULL OR shipping_weight_grams > 0),
  committed_at INTEGER,
  amendment_line_id TEXT REFERENCES paid_order_amendment_line(id)
,
  CHECK ("quantity" IS NULL OR "quantity" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("quantity_sellable" IS NULL OR "quantity_sellable" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("quantity_base_total" IS NULL OR "quantity_base_total" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("shipping_weight_grams" IS NULL OR "shipping_weight_grams" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("committed_at" IS NULL OR "committed_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK (NOT (demand_basis = 'EXACT_PAID_LINE') OR ((
  (order_item_id IS NOT NULL) != (amendment_line_id IS NOT NULL)
  AND sku_id IS NOT NULL
  AND quantity_sellable > 0
  AND quantity_base_total > 0
  AND quantity = quantity_base_total
  AND base_unit_code IS NOT NULL
  AND shipping_weight_grams > 0
  AND committed_at IS NOT NULL
)) IS TRUE)
) STRICT;

