  user_confirmed_at INTEGER,
  delivery_instructions_json TEXT
,
  CHECK ("resolution_version" IS NULL OR "resolution_version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("serviceable" IS NULL OR "serviceable" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("user_confirmed_at" IS NULL OR "user_confirmed_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

