CREATE TABLE "delivery_event" (
  id TEXT PRIMARY KEY NOT NULL,
  delivery_job_id TEXT NOT NULL REFERENCES delivery_job(id) ON DELETE RESTRICT,
  delivery_stop_id TEXT REFERENCES delivery_stop(id) ON DELETE RESTRICT,
