  event_type TEXT NOT NULL CHECK (length(event_type) > 0),
  occurred_at INTEGER NOT NULL,
  recorded_at INTEGER NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  idempotency_key TEXT
,
  CHECK ("occurred_at" IS NULL OR "occurred_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("recorded_at" IS NULL OR "recorded_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_fee_configuration" (
  id TEXT NOT NULL PRIMARY KEY,
  market_id TEXT NOT NULL REFERENCES market(id) ON DELETE RESTRICT,
  location_id TEXT NOT NULL REFERENCES fulfillment_location(id) ON DELETE RESTRICT,
  currency TEXT NOT NULL,
  minimum_delivery_fee_minor INTEGER NOT NULL CHECK (minimum_delivery_fee_minor >= 0),
  per_kilometer_rate_minor INTEGER NOT NULL CHECK (per_kilometer_rate_minor >= 0),
  status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'RETIRED')),
  version INTEGER NOT NULL CHECK (version >= 1),
  effective_from INTEGER NOT NULL,
  effective_to INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (location_id, version),
  CHECK (effective_to IS NULL OR effective_to > effective_from)
,
  CHECK ("minimum_delivery_fee_minor" IS NULL OR "minimum_delivery_fee_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("per_kilometer_rate_minor" IS NULL OR "per_kilometer_rate_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("effective_from" IS NULL OR "effective_from" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("effective_to" IS NULL OR "effective_to" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_job" (
  id TEXT PRIMARY KEY NOT NULL,
  order_id TEXT NOT NULL REFERENCES grocery_order(id) ON DELETE RESTRICT UNIQUE,
  batch_id TEXT REFERENCES delivery_batch(id) ON DELETE RESTRICT,
  sequence INTEGER CHECK (sequence IS NULL OR sequence > 0),
  cycle_id TEXT REFERENCES delivery_cycle(id) ON DELETE RESTRICT,
  fulfillment_mode TEXT NOT NULL DEFAULT 'SCHEDULED'
    CHECK (fulfillment_mode IN ('INSTANT', 'SCHEDULED')),
  location_id TEXT REFERENCES fulfillment_location(id) ON DELETE RESTRICT,
  zone_id TEXT REFERENCES delivery_zone(id) ON DELETE RESTRICT,
  rider_id TEXT REFERENCES rider_identity(id) ON DELETE RESTRICT,
  rider_user_id TEXT,
  promised_at INTEGER,
  status TEXT NOT NULL CHECK (
    status IN ('UNASSIGNED', 'ASSIGNED', 'EN_ROUTE', 'ARRIVED', 'DELIVERED', 'FAILED', 'RETRY_SCHEDULED', 'ESCALATED', 'CANCELED')
  ),
  context_resolution_status TEXT NOT NULL DEFAULT 'RESOLVED'
    CHECK (context_resolution_status IN ('RESOLVED', 'LEGACY_UNRESOLVED')),
  address_snapshot_json TEXT NOT NULL,
  delivered_at INTEGER,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL DEFAULT 0,
  CHECK (
    (
      context_resolution_status = 'RESOLVED'
      AND location_id IS NOT NULL
      AND zone_id IS NOT NULL
      AND (
        (fulfillment_mode = 'INSTANT' AND cycle_id IS NULL)
        OR (fulfillment_mode = 'SCHEDULED' AND cycle_id IS NOT NULL)
      )
    )
    OR (
      context_resolution_status = 'LEGACY_UNRESOLVED'
      AND fulfillment_mode = 'SCHEDULED'
      AND cycle_id IS NULL
      AND location_id IS NULL
      AND zone_id IS NULL
      AND status = 'ESCALATED'
    )
  ),
  CHECK ((batch_id IS NULL) = (sequence IS NULL))
,
  CHECK ("sequence" IS NULL OR "sequence" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("promised_at" IS NULL OR "promised_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("delivered_at" IS NULL OR "delivered_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_job_compatibility_history" (
  delivery_job_id TEXT PRIMARY KEY NOT NULL,
  original_order_id TEXT NOT NULL,
  original_cycle_id TEXT,
  original_fulfillment_mode TEXT NOT NULL,
  original_rider_user_id TEXT,
  original_status TEXT NOT NULL,
  original_address_snapshot_json TEXT NOT NULL,
  original_delivered_at INTEGER,
  original_version INTEGER NOT NULL,
  original_created_at INTEGER NOT NULL,
  original_updated_at INTEGER NOT NULL,
  preserved_at INTEGER NOT NULL DEFAULT 0
,
  CHECK ("original_delivered_at" IS NULL OR "original_delivered_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("original_version" IS NULL OR "original_version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("original_created_at" IS NULL OR "original_created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("original_updated_at" IS NULL OR "original_updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("preserved_at" IS NULL OR "preserved_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_proof" (
  id TEXT PRIMARY KEY NOT NULL,
  delivery_stop_id TEXT NOT NULL UNIQUE REFERENCES delivery_stop(id) ON DELETE RESTRICT,
  rider_id TEXT REFERENCES rider_identity(id) ON DELETE RESTRICT,
  delivered_at INTEGER,
  r2_key TEXT,
  recipient_name TEXT,
  signature_r2_key TEXT,
  metadata_json TEXT NOT NULL,
  created_at INTEGER NOT NULL
,
  CHECK ("delivered_at" IS NULL OR "delivered_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_provider_command" (
  id TEXT PRIMARY KEY NOT NULL,
  dispatch_id TEXT NOT NULL REFERENCES delivery_provider_dispatch(id),
  operation TEXT NOT NULL CHECK (operation IN ('REFRESH','CANCEL')),
  idempotency_scope TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  actor_user_id TEXT NOT NULL,
  location_id TEXT NOT NULL REFERENCES fulfillment_location(id),
  request_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('SUBMITTING','OUTCOME_UNKNOWN','OBSERVED','SUCCEEDED','REJECTED')),
  observation_id TEXT REFERENCES delivery_provider_event_inbox(id),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE(idempotency_scope,idempotency_key)
,
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_provider_dispatch" (
  id TEXT PRIMARY KEY NOT NULL,
  attempt_sequence INTEGER NOT NULL DEFAULT 1 CHECK (attempt_sequence BETWEEN 1 AND 9007199254740991),
  method TEXT NOT NULL DEFAULT 'EXTERNAL' CHECK (method IN ('EXTERNAL','MANUAL')),
  manual_reason TEXT,
  manual_person_name TEXT,
  manual_phone_e164 TEXT,
  handed_over_at INTEGER CHECK (handed_over_at IS NULL OR handed_over_at BETWEEN 0 AND 9007199254740991),
  completed_at INTEGER CHECK (completed_at IS NULL OR completed_at BETWEEN 0 AND 9007199254740991),
  delivery_job_id TEXT NOT NULL REFERENCES delivery_job(id) ON DELETE RESTRICT,
  provider TEXT CHECK (provider IN ('grab-express', 'lalamove')),
  merchant_order_id TEXT NOT NULL UNIQUE,
  provider_delivery_id TEXT UNIQUE,
  request_hash TEXT NOT NULL,
  request_snapshot_json TEXT NOT NULL,
  status TEXT NOT NULL CHECK (
    status IN (
      'PENDING',
      'CREATING',
      'RETRY_REQUIRED',
      'ACTIVE',
      'COMPLETED',
      'CANCELED',
      'RETURNED',
      'FAILED',
      'OUTCOME_UNKNOWN',
      'RECONCILIATION_REQUIRED'
    )
  ),
  provider_status TEXT,
  provider_observed_at INTEGER,
  provider_status_rank INTEGER CHECK (provider_status_rank IS NULL OR provider_status_rank >= 0),
  tracking_url TEXT,
  pickup_pin TEXT,
  quote_amount_minor INTEGER CHECK (quote_amount_minor IS NULL OR quote_amount_minor >= 0),
  quote_currency TEXT,
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  last_error_code TEXT,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  checkout_quotation_id TEXT REFERENCES delivery_provider_quotation(id),
  final_quotation_id TEXT REFERENCES delivery_provider_quotation(id),
  pickup_timing TEXT CHECK (pickup_timing IS NULL OR pickup_timing IN ('IMMEDIATE', 'SCHEDULED')),
  scheduled_pickup_at INTEGER,
  final_payable_minor INTEGER CHECK (final_payable_minor IS NULL OR final_payable_minor >= 0),
  customer_delivery_charge_minor INTEGER
    CHECK (customer_delivery_charge_minor IS NULL OR customer_delivery_charge_minor >= 0),
  courier_variance_minor INTEGER,
  delivery_currency TEXT CHECK (delivery_currency IS NULL OR length(delivery_currency) = 3),
  client_idempotency_key TEXT,
  CHECK (
    (quote_amount_minor IS NULL AND quote_currency IS NULL)
    OR (quote_amount_minor IS NOT NULL AND quote_currency IS NOT NULL)
  ),
  CHECK (
    (provider_observed_at IS NULL AND provider_status_rank IS NULL)
    OR (provider_observed_at IS NOT NULL AND provider_status_rank IS NOT NULL)
  )
,
  CHECK ("provider_observed_at" IS NULL OR "provider_observed_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("provider_status_rank" IS NULL OR "provider_status_rank" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("quote_amount_minor" IS NULL OR "quote_amount_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("attempt_count" IS NULL OR "attempt_count" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("scheduled_pickup_at" IS NULL OR "scheduled_pickup_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("final_payable_minor" IS NULL OR "final_payable_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("customer_delivery_charge_minor" IS NULL OR "customer_delivery_charge_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("courier_variance_minor" IS NULL OR "courier_variance_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK (
    (method='EXTERNAL' AND provider IS NOT NULL AND manual_reason IS NULL AND manual_person_name IS NULL AND manual_phone_e164 IS NULL)
    OR (method='MANUAL' AND provider IS NULL AND provider_delivery_id IS NULL AND client_idempotency_key IS NOT NULL
      AND (length(trim(manual_reason)) BETWEEN 1 AND 1000) IS TRUE
      AND (length(trim(manual_person_name)) BETWEEN 1 AND 120) IS TRUE
      AND (manual_phone_e164 GLOB '+[1-9]*' AND substr(manual_phone_e164,2) NOT GLOB '*[^0-9]*' AND length(manual_phone_e164) BETWEEN 9 AND 16) IS TRUE
    )
  ),
  CHECK (handed_over_at IS NULL OR completed_at IS NULL OR completed_at>=handed_over_at)
) STRICT;

CREATE TABLE "delivery_provider_event_inbox" (
  id TEXT PRIMARY KEY NOT NULL,
  provider TEXT NOT NULL CHECK (provider IN ('grab-express', 'lalamove')),
  provider_event_id TEXT NOT NULL,
  dispatch_id TEXT REFERENCES delivery_provider_dispatch(id) ON DELETE RESTRICT,
  provider_delivery_id TEXT NOT NULL,
  merchant_order_id TEXT NOT NULL,
  observed_at INTEGER NOT NULL,
  provider_status TEXT NOT NULL,
  payload_hash TEXT NOT NULL,
  raw_payload TEXT NOT NULL CHECK (length(raw_payload) <= 65536),
  processing_status TEXT NOT NULL CHECK (
    processing_status IN ('RECEIVED', 'APPLIED', 'RECONCILIATION_REQUIRED')
  ),
  last_error_code TEXT,
  received_at INTEGER NOT NULL,
  processed_at INTEGER,
  recovery_attempts INTEGER NOT NULL DEFAULT 0 CHECK (recovery_attempts >= 0),
  next_recovery_at INTEGER NOT NULL DEFAULT 0,
  UNIQUE(provider, provider_event_id)
,
  CHECK ("observed_at" IS NULL OR "observed_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("received_at" IS NULL OR "received_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("processed_at" IS NULL OR "processed_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("recovery_attempts" IS NULL OR "recovery_attempts" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("next_recovery_at" IS NULL OR "next_recovery_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_provider_quotation" (
  id TEXT PRIMARY KEY NOT NULL,
  checkout_attempt_id TEXT REFERENCES checkout_attempts(id) ON DELETE RESTRICT,
  delivery_job_id TEXT REFERENCES delivery_job(id) ON DELETE RESTRICT,
  provider TEXT NOT NULL,
  provider_service TEXT NOT NULL,
  provider_quotation_id TEXT NOT NULL,
  amount_minor INTEGER NOT NULL CHECK (amount_minor >= 0),
  currency TEXT NOT NULL CHECK (length(currency) = 3),
  quoted_at INTEGER NOT NULL,
  expires_at INTEGER,
  scheduled_pickup_at INTEGER,
  origin_snapshot_json TEXT NOT NULL,
  destination_snapshot_json TEXT NOT NULL,
  capability_snapshot_json TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  status TEXT NOT NULL CHECK (
    status IN ('ACTIVE', 'SELECTED', 'EXPIRED', 'SUPERSEDED', 'FAILED')
  ),
  created_at INTEGER NOT NULL,
  UNIQUE (provider, provider_quotation_id),
  CHECK (
    (checkout_attempt_id IS NOT NULL AND delivery_job_id IS NULL) OR
    (checkout_attempt_id IS NULL AND delivery_job_id IS NOT NULL)
  ),
  CHECK (expires_at IS NULL OR expires_at > quoted_at)
,
  CHECK ("amount_minor" IS NULL OR "amount_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("quoted_at" IS NULL OR "quoted_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("expires_at" IS NULL OR "expires_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("scheduled_pickup_at" IS NULL OR "scheduled_pickup_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_stop" (
  id TEXT PRIMARY KEY NOT NULL,
  delivery_job_id TEXT NOT NULL REFERENCES delivery_job(id) ON DELETE RESTRICT,
  batch_id TEXT REFERENCES delivery_batch(id) ON DELETE RESTRICT,
  sequence INTEGER CHECK (sequence IS NULL OR sequence > 0),
  latitude REAL,
  longitude REAL,
  address_snapshot_json TEXT NOT NULL DEFAULT '{}',
  contact_snapshot_json TEXT NOT NULL DEFAULT '{"recipient":null,"phone":null}',
  instructions_snapshot TEXT,
  status TEXT NOT NULL CHECK (
    status IN ('UNASSIGNED', 'ASSIGNED', 'EN_ROUTE', 'ARRIVED', 'DELIVERED', 'FAILED', 'RETRY_SCHEDULED', 'ESCALATED', 'CANCELED')
  ),
  proof_json TEXT,
  arrived_at INTEGER,
  delivered_at INTEGER,
  failure_reason_code TEXT,
  failure_notes TEXT,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL DEFAULT 0,
  CHECK ((batch_id IS NULL) = (sequence IS NULL)),
  CHECK ((latitude IS NULL) = (longitude IS NULL)),
  CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180)
,
  CHECK ("sequence" IS NULL OR "sequence" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("arrived_at" IS NULL OR "arrived_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("delivered_at" IS NULL OR "delivered_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_stop_compatibility_history" (
  delivery_stop_id TEXT PRIMARY KEY NOT NULL,
  original_batch_id TEXT,
  delivery_job_id TEXT NOT NULL,
  original_sequence INTEGER,
  original_status TEXT NOT NULL,
  proof_json TEXT,
  original_version INTEGER NOT NULL,
  preserved_at INTEGER NOT NULL DEFAULT 0
,
  CHECK ("original_sequence" IS NULL OR "original_sequence" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("original_version" IS NULL OR "original_version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("preserved_at" IS NULL OR "preserved_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "delivery_zone" (
