,
  CHECK ("fee_minor" IS NULL OR "fee_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("instant_fee_minor" IS NULL OR "instant_fee_minor" BETWEEN -9007199254740991 AND 9007199254740991)
