  event_type TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  occurred_at INTEGER NOT NULL
,
  CHECK ("occurred_at" IS NULL OR "occurred_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "finance_exception" (
  id TEXT NOT NULL PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN (
    'QUOTE_EXPIRED',
    'QUOTE_ALREADY_CONSUMED',
    'MEMBERSHIP_LOST',
    'CYCLE_CLOSED',
    'CAPACITY_UNAVAILABLE',
    'CAPACITY_UNAVAILABLE_AFTER_PAYMENT',
    'INSTANT_MODE_UNAVAILABLE',
    'SOURCING_MODE_UNAVAILABLE',
    'STOCK_UNAVAILABLE',
    'TRANSIENT_FAILURE'
  )),
  payment_intent_id TEXT REFERENCES payment_intent(id),
  reaction_id TEXT,
  order_id TEXT,
  details_json TEXT NOT NULL DEFAULT '{}',
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  last_error_code TEXT,
  status TEXT NOT NULL CHECK (status IN ('OPEN','RESOLVED')),
  created_at INTEGER NOT NULL,
  resolved_at INTEGER
,
  CHECK ("attempts" IS NULL OR "attempts" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("resolved_at" IS NULL OR "resolved_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "fulfillment_location" (
  id TEXT PRIMARY KEY NOT NULL,
  market_id TEXT NOT NULL REFERENCES market(id) ON DELETE RESTRICT,
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('FULFILLMENT_CENTER', 'SATELLITE', 'CROSS_DOCK', 'DISPATCH_ONLY', 'PICKUP_POINT')),
