  CHECK (is_default IN (0, 1)),
  UNIQUE (market_id, code),
  CHECK (latitude >= -90 AND latitude <= 90),
  CHECK (longitude >= -180 AND longitude <= 180)
,
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("is_default" IS NULL OR "is_default" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "fulfillment_location_delivery_profile" (
  location_id TEXT PRIMARY KEY NOT NULL
    REFERENCES fulfillment_location(id) ON DELETE RESTRICT,
  sender_name TEXT NOT NULL CHECK (length(trim(sender_name)) BETWEEN 1 AND 120),
  phone_e164 TEXT NOT NULL CHECK (
    phone_e164 GLOB '+[1-9]*' AND substr(phone_e164, 2) NOT GLOB '*[^0-9]*' AND length(phone_e164) BETWEEN 9 AND 16
  ),
  email TEXT,
  formatted_address TEXT NOT NULL CHECK (length(trim(formatted_address)) BETWEEN 1 AND 500),
  address_line1 TEXT NOT NULL CHECK (length(trim(address_line1)) BETWEEN 1 AND 200),
  address_line2 TEXT,
  barangay TEXT,
  city TEXT NOT NULL CHECK (length(trim(city)) BETWEEN 1 AND 120),
  region TEXT,
  postal_code TEXT,
  country_code TEXT NOT NULL CHECK (length(country_code) = 2),
  pickup_instructions TEXT CHECK (
    pickup_instructions IS NULL OR length(pickup_instructions) <= 1000
  ),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
,
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "fulfillment_location_readiness" (
  location_id TEXT PRIMARY KEY NOT NULL REFERENCES fulfillment_location(id) ON DELETE CASCADE,
  instant_promise_minutes INTEGER CHECK (instant_promise_minutes IS NULL OR instant_promise_minutes > 0),
  max_concurrent_instant_orders INTEGER CHECK (
    max_concurrent_instant_orders IS NULL OR max_concurrent_instant_orders > 0
  ),
  dispatch_ready INTEGER NOT NULL DEFAULT 0 CHECK (dispatch_ready IN (0, 1)),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
,
  CHECK ("instant_promise_minutes" IS NULL OR "instant_promise_minutes" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("max_concurrent_instant_orders" IS NULL OR "max_concurrent_instant_orders" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("dispatch_ready" IS NULL OR "dispatch_ready" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
