CREATE TABLE "grocery_order" (
  id TEXT NOT NULL PRIMARY KEY,
  customer_id TEXT NOT NULL REFERENCES customer(id),
  cycle_id TEXT REFERENCES delivery_cycle(id),
  fulfillment_mode TEXT NOT NULL DEFAULT 'SCHEDULED' CHECK (fulfillment_mode IN ('INSTANT', 'SCHEDULED')),
  address_snapshot_json TEXT NOT NULL,
  status TEXT NOT NULL,
  total_minor INTEGER NOT NULL,
  currency TEXT NOT NULL,
  payment_id TEXT NOT NULL REFERENCES payment_attempt(id),
  version INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  merchandise_subtotal_minor INTEGER NOT NULL DEFAULT 0
  CHECK (merchandise_subtotal_minor >= 0),
  item_discount_minor INTEGER NOT NULL DEFAULT 0
  CHECK (item_discount_minor >= 0),
  order_discount_minor INTEGER NOT NULL DEFAULT 0
  CHECK (order_discount_minor >= 0),
  delivery_subtotal_minor INTEGER NOT NULL DEFAULT 0
  CHECK (delivery_subtotal_minor >= 0),
  delivery_discount_minor INTEGER NOT NULL DEFAULT 0
  CHECK (delivery_discount_minor >= 0),
  service_fee_minor INTEGER NOT NULL DEFAULT 0
  CHECK (service_fee_minor >= 0),
  tax_minor INTEGER NOT NULL DEFAULT 0
  CHECK (tax_minor >= 0),
  order_number TEXT,
  committed_at INTEGER,
  pre_service_fee_total_minor INTEGER NOT NULL DEFAULT 0
  CHECK (pre_service_fee_total_minor >= 0),
  service_fee_configuration_id TEXT
  REFERENCES service_fee_configuration(id),
  service_fee_snapshot_json TEXT,
  CHECK ((fulfillment_mode = 'SCHEDULED') = (cycle_id IS NOT NULL))
,
  CHECK ("total_minor" IS NULL OR "total_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("merchandise_subtotal_minor" IS NULL OR "merchandise_subtotal_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("item_discount_minor" IS NULL OR "item_discount_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("order_discount_minor" IS NULL OR "order_discount_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("delivery_subtotal_minor" IS NULL OR "delivery_subtotal_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("delivery_discount_minor" IS NULL OR "delivery_discount_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("service_fee_minor" IS NULL OR "service_fee_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("tax_minor" IS NULL OR "tax_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("committed_at" IS NULL OR "committed_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("pre_service_fee_total_minor" IS NULL OR "pre_service_fee_total_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK (total_minor >= 0)
) STRICT;

