,
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("approved_at" IS NULL OR "approved_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

