    'CUSTOMER_REQUEST','STOCK_UNAVAILABLE','OPERATIONAL_FAILURE',
    'FAILED_DELIVERY','DUPLICATE_CHARGE','DAMAGED_GOODS','OTHER'
  )),
  reason TEXT NOT NULL CHECK (length(trim(reason)) > 0),
  status TEXT NOT NULL
    CHECK (status IN ('REQUESTED','REFUNDS_PROCESSING','COMPLETED','EXCEPTION')),
  retained_service_fee_minor INTEGER NOT NULL
    CHECK (retained_service_fee_minor >= 0),
  required_refund_minor INTEGER NOT NULL CHECK (required_refund_minor >= 0),
  currency TEXT NOT NULL CHECK (length(currency) = 3),
  version INTEGER NOT NULL CHECK (version >= 1),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
,
  CHECK ("retained_service_fee_minor" IS NULL OR "retained_service_fee_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("required_refund_minor" IS NULL OR "required_refund_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

