    'NOT_REQUESTED','REQUESTED','APPROVED','PROCESSING','SUCCEEDED',
    'REJECTED','FAILED','ESCALATED'
  )),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
,
  CHECK ("required_amount_minor" IS NULL OR "required_amount_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("attempts" IS NULL OR "attempts" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "order_fulfillment_snapshot" (
  order_id TEXT NOT NULL REFERENCES grocery_order(id) ON DELETE RESTRICT PRIMARY KEY,
  location_id TEXT NOT NULL,
  cycle_id TEXT REFERENCES delivery_cycle(id),
  zone_id TEXT NOT NULL,
  cutoff_at INTEGER,
  delivery_date INTEGER,
  promised_at INTEGER,
  fulfillment_mode TEXT NOT NULL CHECK (fulfillment_mode IN ('INSTANT', 'SCHEDULED')),
  sourcing_modes_json TEXT NOT NULL,
  created_at INTEGER NOT NULL,
