  CHECK (checkout_delivery_charge_minor IS NULL OR checkout_delivery_charge_minor >= 0),
  CHECK ((fulfillment_mode = 'SCHEDULED') = (cycle_id IS NOT NULL)),
  CHECK ((fulfillment_mode = 'SCHEDULED') = (cutoff_at IS NOT NULL AND delivery_date IS NOT NULL))
,
  CHECK ("cutoff_at" IS NULL OR "cutoff_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("delivery_date" IS NULL OR "delivery_date" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("promised_at" IS NULL OR "promised_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("checkout_delivery_charge_minor" IS NULL OR "checkout_delivery_charge_minor" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "order_invoice_readiness" (
  id TEXT NOT NULL PRIMARY KEY,
