  invoice_identifier TEXT,
  issued_at INTEGER,
  seller_snapshot_json TEXT,
  buyer_snapshot_json TEXT NOT NULL,
  financial_snapshot_json TEXT NOT NULL,
  tax_breakdown_json TEXT,
