  tax_classifications_json TEXT,
  external_reference TEXT,
  blocked_reason TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  CHECK (
    status != 'ISSUED' OR (
      invoice_identifier IS NOT NULL AND issued_at IS NOT NULL AND
      seller_snapshot_json IS NOT NULL AND tax_breakdown_json IS NOT NULL
    )
  )
,
  CHECK ("issued_at" IS NULL OR "issued_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "order_issue" (
  id TEXT NOT NULL PRIMARY KEY,
  order_id TEXT NOT NULL REFERENCES grocery_order(id),
  customer_id TEXT NOT NULL REFERENCES customer(id),
  category TEXT NOT NULL CHECK (category IN ('MISSING_ITEM','WRONG_ITEM','DAMAGED','QUALITY','QUANTITY','DELIVERY','OTHER')),
  status TEXT NOT NULL CHECK (status IN ('SUBMITTED','CLAIMED','INVESTIGATING','RESOLVED','ESCALATED')),
  details TEXT,
  assigned_staff_id TEXT REFERENCES staff_identity(id),
  resolution TEXT,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  idempotency_key TEXT UNIQUE,
  created_at INTEGER NOT NULL,
