CREATE TABLE "procurement_requirement" (
  id TEXT NOT NULL PRIMARY KEY,
  delivery_cycle_id TEXT NOT NULL REFERENCES delivery_cycle(id) ON DELETE RESTRICT,
  location_id TEXT NOT NULL REFERENCES fulfillment_location(id) ON DELETE RESTRICT,
  inventory_pool_id TEXT NOT NULL REFERENCES inventory_pool(id) ON DELETE RESTRICT,
  required_quantity INTEGER NOT NULL,
  status TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL DEFAULT 0,
  procurement_run_id TEXT REFERENCES procurement_run(id),
  sku_id TEXT REFERENCES sku(id),
  calculation_basis TEXT NOT NULL DEFAULT 'LEGACY_COMPATIBILITY'
  CHECK (calculation_basis IN ('LEGACY_COMPATIBILITY', 'EXACT_PAID_DEMAND')),
  committed_quantity_sellable INTEGER
  CHECK (committed_quantity_sellable IS NULL OR committed_quantity_sellable > 0),
  committed_demand_base INTEGER
  CHECK (committed_demand_base IS NULL OR committed_demand_base > 0),
  shipping_weight_grams INTEGER
  CHECK (shipping_weight_grams IS NULL OR shipping_weight_grams > 0),
  required_base INTEGER
  CHECK (required_base IS NULL OR required_base > 0),
  approved_base INTEGER
  CHECK (approved_base IS NULL OR approved_base > 0)
,
  CHECK ("required_quantity" IS NULL OR "required_quantity" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("committed_quantity_sellable" IS NULL OR "committed_quantity_sellable" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("committed_demand_base" IS NULL OR "committed_demand_base" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("shipping_weight_grams" IS NULL OR "shipping_weight_grams" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("required_base" IS NULL OR "required_base" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("approved_base" IS NULL OR "approved_base" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK (NOT (calculation_basis = 'EXACT_PAID_DEMAND') OR ((
  procurement_run_id IS NOT NULL
  AND sku_id IS NOT NULL
  AND committed_quantity_sellable > 0
  AND committed_demand_base > 0
  AND shipping_weight_grams > 0
  AND required_base = committed_demand_base
  AND required_quantity = required_base
)) IS TRUE)
) STRICT;

