    OR (fee_type = 'PERCENTAGE' AND flat_minor = 0 AND percentage_basis_points > 0)
    OR (fee_type = 'MIXED' AND flat_minor > 0 AND percentage_basis_points > 0)
  )
,
  CHECK ("flat_minor" IS NULL OR "flat_minor" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("percentage_basis_points" IS NULL OR "percentage_basis_points" BETWEEN -9007199254740991 AND 9007199254740991),
