  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  merchandising_label TEXT,
  sell_quantity INTEGER NOT NULL DEFAULT 1 CHECK (sell_quantity > 0),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  estimated_shipping_weight_grams INTEGER
  CHECK (estimated_shipping_weight_grams IS NULL OR estimated_shipping_weight_grams > 0),
  UNIQUE (product_id, name)
,
  CHECK ("consumption_base_quantity" IS NULL OR "consumption_base_quantity" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("sort_order" IS NULL OR "sort_order" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("sell_quantity" IS NULL OR "sell_quantity" BETWEEN -9007199254740991 AND 9007199254740991),
