  CHECK ("estimated_shipping_weight_grams" IS NULL OR "estimated_shipping_weight_grams" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "sku_detail" (
  id TEXT PRIMARY KEY NOT NULL,
  sku_id TEXT NOT NULL REFERENCES sku(id) ON DELETE CASCADE,
  audience TEXT NOT NULL CHECK (audience IN ('CUSTOMER', 'OPERATIONS')),
  label TEXT NOT NULL,
  value TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  UNIQUE(sku_id, audience, label)
,
  CHECK ("sort_order" IS NULL OR "sort_order" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "sku_location_availability" (
  sku_id TEXT NOT NULL REFERENCES sku(id) ON DELETE CASCADE,
  location_id TEXT NOT NULL REFERENCES fulfillment_location(id) ON DELETE CASCADE,
  availability_status TEXT NOT NULL CHECK (availability_status IN ('AVAILABLE', 'UNAVAILABLE')),
  sourcing_mode TEXT NOT NULL DEFAULT 'PLANNED'
    CHECK (sourcing_mode IN ('STOCKED', 'PLANNED', 'ON_DEMAND', 'MIXED')),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  PRIMARY KEY (sku_id, location_id)
,
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "staff_identity" (
  id TEXT PRIMARY KEY NOT NULL,
  auth_user_id TEXT NOT NULL UNIQUE REFERENCES user(id) ON DELETE CASCADE,
  display_name TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  version INTEGER NOT NULL DEFAULT 1
,
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

CREATE TABLE "staff_invitation" (
  id TEXT NOT NULL PRIMARY KEY,
