  CHECK ("trial_ends_at" IS NULL OR "trial_ends_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("created_at" IS NULL OR "created_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("updated_at" IS NULL OR "updated_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("version" IS NULL OR "version" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("billing_starts_at" IS NULL OR "billing_starts_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("current_period_starts_at" IS NULL OR "current_period_starts_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("current_period_ends_at" IS NULL OR "current_period_ends_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("paused_at" IS NULL OR "paused_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("resume_at" IS NULL OR "resume_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("cancel_at_period_end" IS NULL OR "cancel_at_period_end" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("cancellation_requested_at" IS NULL OR "cancellation_requested_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("scheduled_cancellation_at" IS NULL OR "scheduled_cancellation_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("ended_at" IS NULL OR "ended_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("grace_ends_at" IS NULL OR "grace_ends_at" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("nominal_billing_day" IS NULL OR "nominal_billing_day" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("renewal_initiated_through" IS NULL OR "renewal_initiated_through" BETWEEN -9007199254740991 AND 9007199254740991),
  CHECK ("agreed_amount_minor" IS NULL OR "agreed_amount_minor" BETWEEN -9007199254740991 AND 9007199254740991)
) STRICT;

