CREATE TRIGGER notification_outbox_queue_state_insert_guard
BEFORE INSERT ON notification_outbox
WHEN
  (NEW.publication_status = 'PUBLISHED'
   AND (NEW.queue_message_id IS NULL OR NEW.published_at IS NULL))
  OR (NEW.publication_status = 'DEAD_LETTERED' AND NEW.dead_lettered_at IS NULL)
  OR ((NEW.lease_owner IS NULL) != (NEW.lease_expires_at IS NULL))
BEGIN
  SELECT RAISE(ABORT, 'INVALID_NOTIFICATION_QUEUE_STATE');
END;

CREATE TRIGGER notification_outbox_queue_state_update_guard
BEFORE UPDATE OF publication_status, queue_message_id, published_at, lease_owner,
  lease_expires_at, dead_lettered_at
ON notification_outbox
WHEN
  (NEW.publication_status = 'PUBLISHED'
   AND (NEW.queue_message_id IS NULL OR NEW.published_at IS NULL))
  OR (NEW.publication_status = 'DEAD_LETTERED' AND NEW.dead_lettered_at IS NULL)
  OR ((NEW.lease_owner IS NULL) != (NEW.lease_expires_at IS NULL))
BEGIN
  SELECT RAISE(ABORT, 'INVALID_NOTIFICATION_QUEUE_STATE');
END;

CREATE TRIGGER price_version_overlap_insert_guard
BEFORE INSERT ON price_version
WHEN EXISTS (
  SELECT 1 FROM price_version existing
  WHERE existing.sku_id = NEW.sku_id
    AND existing.location_id = NEW.location_id
    AND existing.price_type = NEW.price_type
    AND NEW.valid_from < COALESCE(existing.valid_to, 9223372036854775807)
    AND existing.valid_from < COALESCE(NEW.valid_to, 9223372036854775807)
)
BEGIN
  SELECT RAISE(ABORT, 'OVERLAPPING_LOCATION_PRICE_WINDOW');
END;

CREATE TRIGGER price_version_overlap_update_guard
BEFORE UPDATE OF valid_from, valid_to, location_id, price_type ON price_version
WHEN EXISTS (
  SELECT 1 FROM price_version existing
  WHERE existing.id != NEW.id
    AND existing.sku_id = NEW.sku_id
    AND existing.location_id = NEW.location_id
    AND existing.price_type = NEW.price_type
    AND NEW.valid_from < COALESCE(existing.valid_to, 9223372036854775807)
    AND existing.valid_from < COALESCE(NEW.valid_to, 9223372036854775807)
)
BEGIN
  SELECT RAISE(ABORT, 'OVERLAPPING_LOCATION_PRICE_WINDOW');
END;

CREATE TRIGGER price_version_values_insert_guard
BEFORE INSERT ON price_version
WHEN NEW.amount_minor <= 0
  OR NEW.version <= 0
  OR NEW.valid_from < 0
  OR (NEW.valid_to IS NOT NULL AND NEW.valid_to <= NEW.valid_from)
  OR NEW.currency != (SELECT currency FROM market WHERE id = NEW.market_id)
  OR NEW.market_id != (SELECT market_id FROM fulfillment_location WHERE id = NEW.location_id)
BEGIN
  SELECT RAISE(ABORT, 'INVALID_LOCATION_PRICE_VALUES');
END;

CREATE TRIGGER price_version_values_update_guard
BEFORE UPDATE OF currency, amount_minor, valid_from, valid_to, version, market_id, location_id
ON price_version
WHEN NEW.amount_minor <= 0
  OR NEW.version <= 0
  OR NEW.valid_from < 0
  OR (NEW.valid_to IS NOT NULL AND NEW.valid_to <= NEW.valid_from)
  OR NEW.currency != (SELECT currency FROM market WHERE id = NEW.market_id)
  OR NEW.market_id != (SELECT market_id FROM fulfillment_location WHERE id = NEW.location_id)
BEGIN
  SELECT RAISE(ABORT, 'INVALID_LOCATION_PRICE_VALUES');
END;

CREATE TRIGGER procurement_requirement_canonical_status_insert
BEFORE INSERT ON procurement_requirement
WHEN NEW.status NOT IN ('OPEN','AGGREGATED','REQUIREMENT_APPROVED','ORDERED','PARTIALLY_RECEIVED','RECEIVED','CLOSED','EXCEPTION')
BEGIN SELECT RAISE(ABORT, 'INVALID_PROCUREMENT_STATUS'); END;

CREATE TRIGGER procurement_requirement_canonical_status_update
BEFORE UPDATE OF status ON procurement_requirement
WHEN NEW.status NOT IN ('OPEN','AGGREGATED','REQUIREMENT_APPROVED','ORDERED','PARTIALLY_RECEIVED','RECEIVED','CLOSED','EXCEPTION')
BEGIN SELECT RAISE(ABORT, 'INVALID_PROCUREMENT_STATUS'); END;

CREATE TRIGGER procurement_requirement_exact_insert_guard
BEFORE INSERT ON procurement_requirement
WHEN NEW.calculation_basis = 'EXACT_PAID_DEMAND' AND (
  NEW.procurement_run_id IS NOT NULL
  AND NEW.sku_id IS NOT NULL
  AND NEW.committed_quantity_sellable > 0
  AND NEW.committed_demand_base > 0
  AND NEW.shipping_weight_grams > 0
  AND NEW.required_base = NEW.committed_demand_base
  AND NEW.required_quantity = NEW.required_base
) IS NOT TRUE
BEGIN
  SELECT RAISE(ABORT, 'INVALID_EXACT_PROCUREMENT_REQUIREMENT');
END;

CREATE TRIGGER procurement_requirement_exact_update_guard
BEFORE UPDATE OF procurement_run_id, sku_id, calculation_basis,
  committed_quantity_sellable, committed_demand_base, shipping_weight_grams,
  required_base, required_quantity
ON procurement_requirement
WHEN NEW.calculation_basis = 'EXACT_PAID_DEMAND' AND (
  NEW.procurement_run_id IS NOT NULL
  AND NEW.sku_id IS NOT NULL
  AND NEW.committed_quantity_sellable > 0
  AND NEW.committed_demand_base > 0
  AND NEW.shipping_weight_grams > 0
  AND NEW.required_base = NEW.committed_demand_base
  AND NEW.required_quantity = NEW.required_base
) IS NOT TRUE
BEGIN
  SELECT RAISE(ABORT, 'INVALID_EXACT_PROCUREMENT_REQUIREMENT');
END;

CREATE TRIGGER receiving_record_canonical_status_insert
BEFORE INSERT ON receiving_record
WHEN NEW.status NOT IN ('NOT_STARTED','IN_PROGRESS','DISCREPANCY','COMPLETED','CANCELED')
BEGIN SELECT RAISE(ABORT, 'INVALID_RECEIVING_STATUS'); END;

CREATE TRIGGER receiving_record_canonical_status_update
BEFORE UPDATE OF status ON receiving_record
WHEN NEW.status NOT IN ('NOT_STARTED','IN_PROGRESS','DISCREPANCY','COMPLETED','CANCELED')
BEGIN SELECT RAISE(ABORT, 'INVALID_RECEIVING_STATUS'); END;

CREATE UNIQUE INDEX order_promotion_application_benefit_unique ON order_promotion_application(order_id,IFNULL(amendment_id,''),promotion_id,price_component);

CREATE UNIQUE INDEX order_promotion_application_redemption_unique ON order_promotion_application(redemption_id);

CREATE INDEX inventory_hold_location_pool_held_idx ON checkout_inventory_holds(location_id,inventory_pool_id) WHERE status='HELD';

CREATE INDEX order_item_order_idx ON order_item(order_id,id);

CREATE INDEX paid_order_amendment_line_amendment_idx ON paid_order_amendment_line(amendment_id,created_at,id);

CREATE INDEX payment_attempt_intent_created_idx ON payment_attempt(payment_intent_id,created_at DESC);

CREATE UNIQUE INDEX payment_attempt_provider_reference_unique ON payment_attempt(provider,provider_reference) WHERE provider_reference IS NOT NULL;

CREATE INDEX receiving_record_requirement_idx ON receiving_record(procurement_requirement_id);

CREATE INDEX grocery_order_customer_history_idx ON grocery_order(customer_id,COALESCE(committed_at,created_at) DESC,id DESC);

CREATE UNIQUE INDEX delivery_provider_dispatch_job_sequence_unique ON delivery_provider_dispatch(delivery_job_id,attempt_sequence DESC);

CREATE UNIQUE INDEX delivery_provider_dispatch_active_job_unique ON delivery_provider_dispatch(delivery_job_id) WHERE status NOT IN ('COMPLETED','CANCELED','RETURNED','FAILED');

CREATE TRIGGER delivery_attempt_identity_update BEFORE UPDATE OF delivery_job_id,attempt_sequence,method,provider,merchant_order_id,request_hash,request_snapshot_json,client_idempotency_key,manual_reason,manual_person_name,manual_phone_e164 ON delivery_provider_dispatch
WHEN NEW.delivery_job_id IS NOT OLD.delivery_job_id OR NEW.attempt_sequence IS NOT OLD.attempt_sequence OR NEW.method IS NOT OLD.method
  OR NEW.provider IS NOT OLD.provider OR NEW.merchant_order_id IS NOT OLD.merchant_order_id OR NEW.request_hash IS NOT OLD.request_hash
  OR NEW.request_snapshot_json IS NOT OLD.request_snapshot_json OR NEW.client_idempotency_key IS NOT OLD.client_idempotency_key
  OR NEW.manual_reason IS NOT OLD.manual_reason OR NEW.manual_person_name IS NOT OLD.manual_person_name OR NEW.manual_phone_e164 IS NOT OLD.manual_phone_e164
BEGIN SELECT RAISE(ABORT,'DELIVERY_ATTEMPT_IDENTITY_IMMUTABLE'); END;

CREATE TRIGGER delivery_attempt_history_delete BEFORE DELETE ON delivery_provider_dispatch
BEGIN SELECT RAISE(ABORT,'DELIVERY_ATTEMPT_HISTORY_IMMUTABLE'); END;

CREATE TRIGGER delivery_attempt_pending_cancel_insert BEFORE INSERT ON delivery_provider_dispatch
WHEN EXISTS (SELECT 1 FROM delivery_provider_command command JOIN delivery_provider_dispatch previous ON previous.id=command.dispatch_id
  WHERE previous.delivery_job_id=NEW.delivery_job_id AND command.operation='CANCEL' AND command.status IN ('SUBMITTING','OUTCOME_UNKNOWN','OBSERVED'))
BEGIN SELECT RAISE(ABORT,'DELIVERY_CANCEL_RECONCILIATION_REQUIRED'); END;

